def decimal_to_binary_db(n: int) -> str:
    """
    Converts a decimal integer to a binary string with 'db' prefix and suffix.
    Example: 5 -> 'db101db'
    """
    if n < 0:
        raise ValueError("Negative numbers are not supported")
