def _split_into_blocks(text: str):
    """Yield successive blocks of three characters from the input string."""
    return (text[i:i + 3] for i in range(0, len(text), 3))

def encode(text: str) -> str:
    """
    Encode the input string by rotating each full 3‑character block left.
    Partial blocks (less than 3 characters) are left unchanged.
    """
    return ''.join(
        block[1:] + block[0] if len(block) == 3 else block
        for block in _split_into_blocks(text)
    )

def decode(text: str) -> str:
    """
    Decode the input string by rotating each full 3‑character block right.
    Partial blocks (less than 3 characters) are left unchanged.
    """
    return ''.join(
        block[-1] + block[:-1] if len(block) == 3 else block
        for block in _split_into_blocks(text)
    )

